export interface FeatureSwitch {
  code: string;
  note?: string;
  active: boolean;
}

export interface FeaturePatch {
  note?: string;
  active?: boolean;
}

export class FeatureCatalog {
  private readonly features = new Map<string, FeatureSwitch>();

  private normalizeCode(code: string): string {
    if (typeof code !== "string") {
      throw new Error("Feature code must not be empty");
    }
    const normalized = code.trim();
    if (normalized.length === 0) {
      throw new Error("Feature code must not be empty");
    }
    return normalized;
  }

  insert(code: string, note?: string, active = true): void {
    const normalized = this.normalizeCode(code);
    if (this.features.has(normalized)) {
      throw new Error("Feature already exists");
    }

    const feature: FeatureSwitch = note === undefined
      ? { code: normalized, active }
      : { code: normalized, note, active };
    this.features.set(normalized, feature);
  }

  amend(code: string, patch: FeaturePatch): void {
    const normalized = this.normalizeCode(code);
    const feature = this.features.get(normalized);
    if (feature === undefined) {
      throw new Error("Feature not found");
    }
    if (patch.note !== undefined) {
      feature.note = patch.note;
    }
    if (patch.active !== undefined) {
      feature.active = patch.active;
    }
  }

  drop(code: string): void {
    const normalized = this.normalizeCode(code);
    if (!this.features.delete(normalized)) {
      throw new Error("Feature not found");
    }
  }

  snapshot(): FeatureSwitch[] {
    return [...this.features.values()]
      .sort((left, right) => left.code < right.code ? -1 : left.code > right.code ? 1 : 0)
      .map((feature) => ({ ...feature }));
  }
}

